import json


def extract_json(text: str):
    if not isinstance(text, str):
        return None
    decoder = json.JSONDecoder()
    for i, ch in enumerate(text):
        if ch != '{':
            continue
        try:
            obj, _ = decoder.raw_decode(text, i)
        except Exception:
            continue
        if isinstance(obj, dict):
            return obj
    return None

