    if not isinstance(text, str):
        return None

    decoder = json.JSONDecoder()

    for i, ch in enumerate(text):
        if ch != '{':
            continue
        try:
            obj, _end = decoder.decode(text, i)
        except ValueError:
            continue
        if isinstance(obj, dict):
            return obj

    return None

